head.script:
scwin.onpageload = function() {
    dataList1.setData(["value1", "label1", "value2", "label2", "value3", "label3"]);
    codeList1.setData(["code1", "label1", "code2", "label2", "code3", "label3", "code4", "label4", "code5", "label5"]);
};
scwin.onpageunload = function() {};
scwin.selectbox1_onviewchange = function(info) {
    console.log(info);
    var newValue = info.newValue;
    if (newValue == "value1") {
        codeList1.setData(["code1", "label1", "code2", "label2", "code3", "label3"]);
    } else if (newValue == "value2") {
        codeList1.setData(["code1", "label1", "code2", "label2", "code3", "label3", "code4", "label4", "code5", "label5", "code6", "label6", "code7", "label7"]);
    } else {
        codeList1.setData(["code1", "label1", "code2", "label2", "code3", "label3", "code4", "label4", "code5", "label5", "code6", "label6", "code7", "label7", "code8", "label8", "code9", "label9", "code10", "label10", "code11", "labe11", "code12", "label12", "code13", "label13", "code14", "label14"]);
    }
};
scwin.unitTest = function() {
    //Unit tets
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('selectbox1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('checkcombobox2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('selectbox1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('selectbox1_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('checkcombobox2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#checkcombobox2_itemTable').height() < 200", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
